        }));
        poll_fn(|cx| {
            assert!(fallible.as_mut().poll(cx).is_pending());
            Poll::Ready(())
        }).await;
        let mut infallible = Box::pin(cache.get_with(1, async { 42 }));
        poll_fn(|cx| {
            assert!(infallible.as_mut().poll(cx).is_pending());
            Poll::Ready(())
        }).await;
        tx.send(()).unwrap();
        assert!(fallible.await.is_err());
        assert_eq!(infallible.await, 42);
    }
}
